const input = $input.first().json;
const normalizePhone = (value) => '+' + String(value || '').replace(/\D/g, '');
const adminPhones = ['+573222046768', '+573027697381'];
const customerPhone = normalizePhone(input.customerPhone);
const command = String(input.messageText || '').trim().toLowerCase().split(/\s+/)[0];

if (!adminPhones.includes(customerPhone)) {
  return [{ json: { ...input, isAdmin: false, shouldReply: false, replyText: '' } }];
}

const now = new Date();
const estimatedSleep = new Date(now.getTime() + 15 * 60 * 1000);
const formatBogota = (date) => new Intl.DateTimeFormat('es-CO', {
  timeZone: 'America/Bogota',
  dateStyle: 'short',
  timeStyle: 'medium'
}).format(date);

let replyText;
switch (command) {
  case '#encender':
  case '#estado':
    replyText = [
      '\u2705 *TIC TAC | SISTEMA ACTIVO*',
      '\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501',
      '\u{1F7E2} *n8n:* En l\u00ednea',
      '\u{1F916} *Chatbot:* Operativo',
      `\u{1F552} *Verificado:* ${formatBogota(now)}`,
      '',
      `\u{1F4A4} *Suspensi\u00f3n estimada:* ${formatBogota(estimatedSleep)}`,
      '\u2139\uFE0F El horario es aproximado. Cualquier mensaje, webhook o visita reinicia el contador de inactividad.',
      '\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501',
      '_Tic Tac Agency Performance SAS_'
    ].join('\n');
    break;

  case '#ayuda':
    replyText = [
      '\u{1F6E0}\uFE0F *TIC TAC | PANEL ADMIN*',
      '\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501',
      'Comandos disponibles:',
      '',
      '\u26A1 *#encender*',
      'Despierta Render y confirma que el sistema respondi\u00f3.',
      '',
      '\u{1F50E} *#estado*',
      'Consulta disponibilidad y suspensi\u00f3n estimada.',
      '',
      '\u2753 *#ayuda*',
      'Muestra este panel de comandos.',
      '\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501',
      '\u{1F512} Acceso restringido a números administradores.'
    ].join('\n');
    break;

  default:
    replyText = [
      '\u26A0\uFE0F *COMANDO NO RECONOCIDO*',
      '',
      `No existe el comando *${command || '(vac\u00edo)'}*.`,
      'Env\u00eda *#ayuda* para consultar las opciones disponibles.'
    ].join('\n');
}

return [{ json: { ...input, isAdmin: true, shouldReply: true, adminCommand: command, replyText } }];
